import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();

        System.out.println("第一个比第二个大吗：" + (a > b));
        System.out.println("第一个比 {k} 大吗：" + (a > {k}));
        System.out.println("两个都成立吗：" + (a > b && a > {k}));
    }
}
